function [has, ch] = kpi_kind_channel(kind)
%KPI_KIND_CHANNEL  The channel a pointing kind takes its statistic of: the APE and AKE three-axis and across the boresight, the rate
%   stability; has false for any other kind.
%   kind: MetricKind (passed a choice, as its option's number)
%   returns has: bool (passed true or false)
%   returns ch: MetricChannel (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    has = false;
    ch = 0;
    has = true;
    ch = 0;
    if (kind == 2)
        ch = 1;
    elseif (kind == 3)
        ch = 2;
    elseif (kind == 4)
        ch = 3;
    elseif (kind == 5)
        ch = 5;
    elseif (kind ~= 1)
        has = false;
    end
end
